int smb2_handle_write_op(unsigned int xid, struct cifs_io_parms *io_parms,
                         unsigned int *nbytes, struct kvec *iov, int n_vec) {
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    int rc = 0;

    if (!io_parms || !iov || !nbytes) {
        return -EINVAL;
    }

    req = cifs_buf_get();
    if (!req) {
        return -ENOMEM;
    }

    resp = cifs_buf_get();
    if (!resp) {
        cifs_buf_put(req);
        return -ENOMEM;
    }

    req->hdr.MessageId = cpu_to_le64(xid);
    req->PersistentFileId = io_parms->persistent_fid;
    req->VolatileFileId = io_parms->volatile_fid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->DataLength = cpu_to_le32(io_parms->length);
    req->Channel = 0;

    rc = cifs_send_recv(io_parms->tcon, &req, &resp, iov, n_vec, 0);
    if (rc != 0) {
        cifs_buf_put(req);
        cifs_buf_put(resp);
        return rc;
    }

    *nbytes = le32_to_cpu(resp->DataLength);
    cifs_buf_put(req);
    cifs_buf_put(resp);
    return 0;
}

int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms,
                      unsigned int *nbytes, struct kvec *iov, int n_vec)
{
    int rc = 0;
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    struct TCP_Server_Info *server = io_parms->cfile->tcon->ses->server;

    if (!server || !serverCanDMA(server)) {
        rc = -EIO;
        goto out;
    }

    req = cifs_buf_get();
    if (!req) {
        rc = -ENOMEM;
        goto out;
    }

    resp = cifs_buf_get();
    if (!resp) {
        rc = -ENOMEM;
        goto free_req;
    }

    init_hdr((struct smb2_hdr *)req, SMB2_WRITE, sizeof(*req), server);
    req->PersistentFileId = io_parms->pid;
    req->FileId = io_parms->unique_id;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->RemainingBytes = 0;
    req->DataOffset = cpu_to_le16(offsetof(struct smb2_write_request, Buffer));
    req->DataLength = cpu_to_le32(io_parms->length);
    req->Channel = 0;

    rc = cifs_send_recv(xid, server, req, 0, resp);
    if (rc) {
        cifs_buf_release(req);
        cifs_buf_release(resp);
        goto out;
    }

    if (le32_to_cpu(resp->DataLength) != io_parms->length) {
        cifs_dbg(VFS, "Unexpected response length\n");
        rc = -EIO;
        cifs_buf_release(req);
        cifs_buf_release(resp);
        goto out;
    }

    *nbytes = le32_to_cpu(resp->DataLength);

    cifs_buf_release(req);
    cifs_buf_release(resp);

out:
    return rc;

free_req:
    cifs_buf_release(req);
    goto out;
}

