int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    int rc = 0;
    struct smb2_write_request *req = NULL;
    struct smb2_write_response *resp = NULL;
    struct TCP_Server_Info *server;

    if (!io_parms || !nbytes || !iov) {
        return -EINVAL;
    }

    server = io_parms->tcon->ses->server;
    if (!server) {
        return -EIO;
    }

    req = smb2_plain_req_init(SMB2_WRITE, server, (unsigned char **)&resp);
    if (!req) {
        return -ENOMEM;
    }

    req->PersistentFileId = io_parms->persistent_fid;
    req->FileId = io_parms->volatile_fid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Length = cpu_to_le32(io_parms->length);

    rc = cifs_send_recv(xid, server, (char *)req, iov, n_vec, CIFS_WRITE, &resp);
    if (rc) {
        goto out;
    }

    *nbytes = le32_to_cpu(resp->DataLength);
out:
    kfree(req);
    return rc;
}

int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec)
{
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    int rc = 0;
    int bytes_sent;

    req = cifs_buf_get();
    if (!req) {
        rc = -ENOMEM;
        goto out;
    }

    init_smb2_write_request(req, io_parms->persistent_fid, io_parms->volatile_fid, *nbytes);

    resp = cifs_buf_get();
    if (!resp) {
        rc = -ENOMEM;
        goto out_free_req;
    }

    rc = cifs_send_recv(xid, io_parms->ses, req, &resp, &bytes_sent);
    if (rc != 0)
        goto out_free_all;

    *nbytes = get_smb2_write_data_length(resp);
    cifs_small_buf_release(req);
    cifs_small_buf_release(resp);
    return 0;

out_free_all:
    cifs_small_buf_release(resp);
out_free_req:
    cifs_small_buf_release(req);
out:
    *nbytes = 0;
    return rc;
}
